CREATE TABLE "ProjectKpi" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "metricName" TEXT NOT NULL, "periodStart" DATETIME NOT NULL, "periodEnd" DATETIME NOT NULL, "targetValue" REAL, "actualValue" REAL, "unit" TEXT, "currency" TEXT, "source" TEXT NOT NULL DEFAULT 'MANUAL', "createdById" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
