CREATE TABLE "ProjectSourceFile" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT NOT NULL, "sourceType" TEXT NOT NULL, "originalName" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT, "sizeBytes" INTEGER NOT NULL, "sha256" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'UPLOADED', "importSummary" TEXT NOT NULL DEFAULT '{}', "uploadedById" TEXT NOT NULL, "uploadedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
