CREATE TABLE "ProjectDiscountMapping" ("id" TEXT NOT NULL PRIMARY KEY, "sourceId" TEXT NOT NULL, "externalKey" TEXT NOT NULL, "productId" TEXT, "sku" TEXT, "discountCode" TEXT, "mappingData" TEXT NOT NULL DEFAULT '{}', "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "ProjectDiscountMapping_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "ProjectDiscountSource"("id") ON DELETE CASCADE ON UPDATE CASCADE);
